for rec in records:
    location_type = rec.x_location_type
    parent = rec.x_parent_id

    if location_type == 'region' and parent:
        raise Warning('A region must not have a parent location.')

    if location_type == 'district':
        if not parent or parent.x_location_type != 'region':
            raise Warning('A district must have a region as its parent.')

    if location_type == 'city':
        if not parent or parent.x_location_type != 'district':
            raise Warning('A city must have a district as its parent.')

    if location_type == 'municipality':
        if not parent or parent.x_location_type != 'district':
            raise Warning('A municipality must have a district as its parent.')

    if location_type == 'locality':
        if not parent or parent.x_location_type != 'municipality':
            raise Warning('A locality must have a municipality as its parent.')

